            var subscriptions = new List<Subscription>
            {
                new Subscription(date.Month, date.Year) { Name = "Netflix" },
                new Subscription(date.Month, date.Year) { Name = "Amazon Prime" }
            };

            var user = new User(subscriptions)
            {
                Name = "Mike Mora",
