import M from 'materialize-css';
import React from 'react';
import ReactDOM from 'react-dom';

import getCSRFToken from '../../utils/getCSRFToken';
import deleteRegister from '../common/delete';
import SubjectGraph from './SubjectGraph';
import { ScoreResult } from '../../declaration/models/Score';


export default class Subject {
	constructor() {
		deleteRegister('subject');
		$('td').on('click', '.edit-score', this.editScore);
		$('td').on('click', '.submit-score',this.submitScore);
		this.initializeSubjectGraph();
	}

	public editScore(event: JQuery.ClickEvent): void {
		event.preventDefault();
		const editId = $(event.target).data('id');
		const score = parseFloat($(`.score[data-id="${editId}"]`).html());
		$(event.target).toggleClass('submit-score edit-score').html('submit');
		$(`.score[data-id="${editId}"]`).html(`<input data-id="${editId}" type="number" value=${score} max="100" min="0" step="0.01">`);
	}

	public submitScore(event: JQuery.ClickEvent): void | boolean {
		event.preventDefault();
		const editId = $(event.target).data('id');
		const newScore = $(`input[data-id="${editId}"]`).val();

		if (!newScore) {
			M.toast({
				html: 'input is not a number.',
				classes: 'red'
			});
			return false;
		}

		if (newScore > 100 || newScore < 0) {
			M.toast({
				html: 'input out of range.',
				classes: 'red'
			});
			return false;
		}

		const csrfToken = getCSRFToken();

		const body = JSON.stringify({
			score: newScore,
			pk: editId,
		});

		const headers = new Headers();
		headers.set('Content-Type', 'application/x-www-form-urlencoded');
		headers.set('X-CSRFToken', csrfToken);

		const postNewGrade = fetch('/grade/edit/', {
			headers,
			method: 'POST',
			body,
		});

		postNewGrade
			.then((response) => {
				return response.json();
			})
			.then((data) => {
				M.toast({
					html: data.status,
					classes: 'card-panel teal lighten-2'
				});
				$(`.score[data-id="${editId}"]`).html(data.score);
				$(event.target).toggleClass('submit-score edit-score').html('edit');
				$('#subject-average').html(data.new_average);
			})
			.catch((error) => {
				M.toast({
					html: error,
					classes: 'red'
				});
			});
	}

	public initializeSubjectGraph(): void {
		const container = document.getElementById('score-graph');
		if (container) {
			this.fetchSubjectScores().then(scoreResult => {
				ReactDOM.render(<SubjectGraph subject={scoreResult} />, container);
			});
		}
	}

	public fetchSubjectScores(): Promise<ScoreResult> {
		const requestUrl = `${window.location.pathname}/scores`;
		const headers = new Headers();
		headers.append('Accept-type', 'application/json');
		return fetch(requestUrl, {
			headers,
			credentials: 'include',
		}).then(response => {
			return response.json() as Promise<ScoreResult>;
		});
	}
}

import { useQuery } from '@apollo/client';
import { Paper, Typography } from '@material-ui/core';
import { ButtonOutlined } from 'litmus-ui';
import React, { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { LIST_PROJECTS } from '../../../graphql';
import {
  InvitationStatus,
  Member,
  Project,
  Projects,
  Role,
} from '../../../models/graphql/user';
import useActions from '../../../redux/actions';
import * as TabActions from '../../../redux/actions/tabs';
import { history } from '../../../redux/configureStore';
import { getUserId } from '../../../utils/auth';
import { getProjectID, getProjectRole } from '../../../utils/getSearchParams';
import useStyles from './styles';

const ProjectInfoContainer: React.FC = () => {
  const classes = useStyles();
  const { t } = useTranslation();
  const tabs = useActions(TabActions);

  const userID = getUserId();

  const projectID = getProjectID();
  const projectRole = getProjectRole();

  const [projectOwnerCount, setProjectOwnerCount] = useState<number>(0);
  const [projectOtherCount, setProjectOtherCount] = useState<number>(0);
  const [invitationsCount, setInvitationCount] = useState<number>(0);
  const [projects, setProjects] = useState<Project[]>([]);

  const { data: dataProject } = useQuery<Projects>(LIST_PROJECTS, {
    onCompleted: () => {
      if (dataProject?.listProjects) {
        setProjects(dataProject?.listProjects);
      }
    },
    fetchPolicy: 'cache-and-network',
  });

  useEffect(() => {
    let projectOwner = 0;
    let projectInvitation = 0;
    let projectOther = 0;
    projects.forEach((project) => {
      project.members.forEach((member: Member) => {
        if (member.user_id === userID && member.role === Role.owner) {
          projectOwner++;
        } else if (
          member.user_id === userID &&
          member.invitation === InvitationStatus.PENDING
        ) {
          projectInvitation++;
        } else if (
          member.user_id === userID &&
          member.role !== Role.owner &&
          member.invitation === InvitationStatus.ACCEPTED
        ) {
          projectOther++;
        }
      });
    });
    setProjectOwnerCount(projectOwner);
    setInvitationCount(projectInvitation);
    setProjectOtherCount(projectOther);
  }, [projects, dataProject]);

  const projectCount = projectOwnerCount + projectOtherCount;

  return (
    <div>
      {/* Project Level info container */}
      <Paper className={classes.projectInfoContainer}>
        <div className={classes.projectInfoBlock}>
          <div className={classes.projectInfoData}>
            <div>
              <Typography id="projectCount">{projectCount}</Typography>
              {projectCount === 1 ? (
                <Typography>
                  {t('homeViews.projectInfoContainer.project')}
                </Typography>
              ) : (
                <Typography>
                  {t('homeViews.projectInfoContainer.projects')}
                </Typography>
              )}
            </div>
            <div>
              <Typography id="invitationCount">{invitationsCount}</Typography>
              {invitationsCount === 1 ? (
                <Typography>
                  {t('homeViews.projectInfoContainer.invitation')}
                </Typography>
              ) : (
                <Typography>
                  {t('homeViews.projectInfoContainer.invitations')}
                </Typography>
              )}
            </div>
          </div>
        </div>
        {projectRole === Role.owner && (
          <ButtonOutlined
            onClick={() => {
              tabs.changeSettingsTabs(1);
              history.push({
                pathname: '/settings',
                search: `?projectID=${projectID}&projectRole=${projectRole}`,
              });
            }}
            className={classes.viewProjectButton}
          >
            <Typography>
              <img src="./icons/viewProjects.svg" alt="View projects" />
              {t('homeViews.projectInfoContainer.viewProjects')}
            </Typography>
          </ButtonOutlined>
        )}
      </Paper>
    </div>
  );
};

export default ProjectInfoContainer;

import { StreamingAudioChannel } from './StreamingAudioChannel';
import { WebAudioChannel } from './WebAudioChannel';
import { IAudioChannel } from './IAudioChannel';
import { EventAudioChannel } from './EventAudioChannel';
import { IAudioChannelClass } from './IAudioChannelClass';

export class AudioManager {
	private static isIE: boolean=!!navigator.userAgent.match(/Trident/g) || !!navigator.userAgent.match(/MSIE/g);
	//todo: make AudioPlaybackManager keep track of active sounds + implement global playback control
	private static _externalSoundInterface: any=null;

	private static _channelGroupVolumes: number[]=[1];
	private static _channelGroupPanning: number[]=[0.5];

	public static setVolume(value: number, channelGroup: number = -1): void {
		if (channelGroup < 0) {
			const len: number = AudioManager._channelGroupVolumes.length;
			for (let j: number = 0; j < len; j++) {
				AudioManager._channelGroupVolumes[j] = value;
			}
		} else {
			AudioManager._channelGroupVolumes[channelGroup] = value;
		}
		WebAudioChannel.setChannelGroupVolume(value, channelGroup);
		StreamingAudioChannel.setChannelGroupVolume(value, channelGroup);
		EventAudioChannel.setChannelGroupVolume(value, channelGroup);

	}

	public static getVolume(channelGroup: number = 0): number {
		return AudioManager._channelGroupVolumes[channelGroup];
	}

	public static setExternalSoundInterface(new_obj: any): number {
		if (new_obj.startSound == null) {
			console.log('Could not set the externalSoundInterface, ' +
						'because it does not provide a \'startSound\' function');
			return;
		}
		if (new_obj.stopSound == null) {
			console.log('Could not set the externalSoundInterface, ' +
						'because it does not provide a \'stopSound\' function');
			return;
		}
		AudioManager._externalSoundInterface = new_obj;
	}

	public static getExternalSoundInterface(): any {
		return AudioManager._externalSoundInterface;
	}

	public static stopAllSounds() {
		WebAudioChannel.stopAllSounds();
		StreamingAudioChannel.stopAllSounds();
		EventAudioChannel.stopAllSounds();
		//AudioChannel.stopAllSounds();
	}

	public static getChannel(byteLength: number, channelGroup: number = 0): IAudioChannel {
		//choose best audio channel by bytelength
		//todo: StreamingAudioChannel doesnt seem to be working. no error, but also no sound is playing
		let channelClass: IAudioChannelClass = (byteLength > 50000000) ? StreamingAudioChannel : WebAudioChannel;
		if (AudioManager.isIE) {
			channelClass = EventAudioChannel;
		}
		//var channelClass:IAudioChannelClass = WebAudioChannel;

		let i: number = 0;
		while (channelClass._channels[i] && channelClass._channels[i].isPlaying())
			i++;

		if (i == channelClass.maxChannels) {
			//pick the oldest channel to reuse, ignoring looping channels
			let channel: IAudioChannel;
			const len: number = channelClass._channels.length;
			for (let j: number = 0; j < len; j++) {
				channel = channelClass._channels[j];
				if (!channel.isLooping() && !channel.isDecoding()) {
					channel.groupID = channelGroup;
					channel.groupVolume = AudioManager._channelGroupVolumes[channelGroup];
					channel.groupPan = AudioManager._channelGroupPanning[channelGroup];
					channelClass._channels.push(channelClass._channels.splice(j, 1)[0]);
					channel.stop();
					return channel;
				}
			}

			//do not return channel until one is freed up
			return null;
		}

		return  (channelClass._channels[i] = new channelClass(channelGroup,
			AudioManager._channelGroupVolumes[channelGroup],
			AudioManager._channelGroupPanning[channelGroup]));
	}

}

