int CNAME(BLASLONG n, FLOAT *x, BLASLONG inc_x, FLOAT *y, BLASLONG inc_y)
{
	BLASLONG i=0;
	BLASLONG ix=0,iy=0;

	if ( n < 0     )  return(0);

	BLASLONG inc_x2 = 2 * inc_x;
	BLASLONG inc_y2 = 2 * inc_y;

	while(i < n)
	{

		y[iy]   = x[ix] ;
		y[iy+1] = x[ix+1] ;
		ix += inc_x2;
		iy += inc_y2;
		i++ ;

	}
	return(0);

}

