    margin-top:20pt;
    margin-right:30pt;
    text-align: center;
    border:solid 2px;
    min-width:130pt;
}

#profile-image-upload div{
    padding-top:10pt;
}

#profile-image-upload > div + div,
#profile-image-upload:hover > div,
#profile-image-upload:hover .fa,
#profile-image-upload > .fa + .fa{
    display:none;
}
#profile-image-upload:hover{
