#profile-image-upload:hover > .fa + .fa {
    display:block;
}


/****************************************************************
***************---- CSS STYLING for the ----*********************
************------  Interview list page -----********************
*****************************************************************/

.search-button{
    display: inline-block;
    position:absolute;
    right:30px;
    top: 0.8rem;
}
.search-button:hover{
    transform: scale(1.3)

}
.search-input{
    padding-right:35px;
    margin-bottom: 30pt;
}
.search-input:hover + i {
    transform:scale(1.3);
}
.search-input:hover{
    transform:scale(1,1.08);
    box-shadow: 2px 1px lightgrey   ;
}

.card{
    margin-right:10px;
    margin-left:10px;
    width: 110pt;
    margin-bottom:15px;
}

.card-hover-effect .card-body {
    margin-top:10px;
}

.card-hover-effect .card-body .card-subtitle {
    margin-bottom:15px;
}

.card-control{
    padding: 6pt;
    position:absolute;
    right: 4pt;
    top: 4pt;
    font-size:14pt;
}

.card-hover-effect .card-control {
    display:none;
}

.card-hover-effect:hover .card-control {
    display:block;
}

.card-hover-effect:hover {
    transform: scale(1.04);
    box-shadow: 1px 3px lightgrey;
}

.card-control-shadowed {
    background-color: silver;
    border: solid 2px cornflowerblue;
    border-radius: 3px;
    animation: fadein .2s;
}

@keyframes fadein {
    from {
        transform: scale(0.2);
    }
    to {
        transform: scale(1);
    }
}

