/* BOTONES */
.btn-icon::before {
content: "\e00d";
}

.btn{
    font-size: 15px;
    padding: 17px 50px;
    border: none;
    font-family: inherit;
    font-size: inherit;
    color: inherit;
    background: none;
    cursor: pointer;
    display: inline-block;
    font-weight: 400;
    outline: none;
    position: relative;
    -webkit-transition: all 0.3s;
    -moz-transition: all 0.3s;
    transition: all 0.3s;
    font-family: 'Montserrat';
  }
.btn::before{
  font-family: 'icomoon';
    speak: none;
    font-style: normal;
    font-weight: normal;
    font-variant: normal;
    text-transform: none;
    line-height: 1;
    position: relative;
    -webkit-font-smoothing: antialiased;
}

.btn::after{
  content: '';
  position: absolute;
  z-index: -1;
  -webkit-transition: all 0.3s;
  -moz-transition: all 0.3s;
  transition: all 0.3s;
}

.btn-action:before {
  position: absolute;
  height: 100%;
  font-size: 125%;
  line-height: 3.5;
  color: #fff;
  -webkit-transition: all 0.3s;
  -moz-transition: all 0.3s;
  transition: all 0.3s;
}

.btn-action {
    border-radius: 50px;
    border: 0;
    background: #e92828;
    color: #fff;
    overflow: hidden;
}

.btn-action:hover,.btn-action:focus, .btn-action:active  {
    background: #ca2323;
    color: #fff;
}


.btn-action-b::before {
    left: 70%;
    opacity: 0;
    top: -3px;
}

.btn-action-b:hover:before{
    left: 80%;
    opacity: 1;
    top: -3px;
    pointer-events: none;
}




.btn-third-action {
    background: #e92828;
    border-radius: 30px;
    padding: 10px 30px;
    color: #fff;
    transition: all 0.3s ease 0s;
    margin: 0 10px;

}

.btn-third-action:hover, .btn-third-action:active, .btn-third-action:focus {
    background: #cb1818;
    border-radius: 30px;
    padding: 10px 30px;
    color: #fff;
    transition: all 0.3s ease 0s;
}




.btn-second-action {
    background: #fff;
    border-radius: 30px;
    padding: 10px 30px;
