/* Модальное окно "Героя" */
.backdrop {
    /* серый фон */
    position: fixed;
    top: 0;
    left: 0;

    width: 100%;
    height: 100%;

    background-color: rgba(0, 0, 0, 0.2);

    transition: opacity 250ms cubic-bezier(0.4, 0, 0.2, 1);
  }
  .backdrop.is-hidden {
    opacity: 0;
    pointer-events: none;
  }
  .backdrop.is-hidden .modal {
    transform: translate(-50%) scale(1.5);
  }
  .modal {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) scale(1);
    transition: transform 250ms cubic-bezier(0.4, 0, 0.2, 1);
    min-width: 528px;
    min-height: 581px;
    background-color: #FFFFFF;
    box-shadow: 0px 1px 3px rgba(0, 0, 0, 0.12), 0px 1px 1px rgba(0, 0, 0, 0.14), 0px 2px 1px rgba(0, 0, 0, 0.2);
    border-radius: 4px;
  }
  .close {
    /* кнопка закрытия мод окна */
    position: absolute;
    top: 8px;
    right: 8px;

    display: flex;
    align-items: center;
    justify-content: center;

    width: 30px;
    height: 30px;
    margin: 0;
    padding: 0;

    background-color: #ffffff;
    border: 1px solid rgba(0, 0, 0, 0.1);
    border-radius: 50%;
  }
  .icon-close {
    fill:  #000000;
    transition: fill 250ms cubic-bezier(0.4, 0, 0.2, 1);
  }
  .close:hover .icon-close {
    fill: #2196f3;
  }
  .close:hover {
    cursor: pointer;
  }
  .modal > form {
    box-sizing: content-box;

    width: 448px;
    padding-left: 40px;
    padding-right: 40px;
    padding-top: 40px;
    padding-bottom: 40px;
  }
  .form-title {
    display: inline-block;

    font-weight: 700;
    font-size: 20px;
    line-height: 1.15;
    text-align: center;
    letter-spacing: 0.03em;

    color: #212121;
    margin-bottom: 12px;
  }
  .form-field {
    position: relative;

    display: flex;
    flex-direction: column;

    margin-bottom: 10px;
  }
  .form-field > label {
    margin-bottom: 4px;

    font-size: 12px;
    line-height: 1.17;
    letter-spacing: 0.01em;
  }
  .form-field > input {
    border: 1px solid rgba(33, 33, 33, 0.2);
    border-radius: 4px;
    transition: border-color 250ms cubic-bezier(0.4, 0, 0.2, 1);

    padding-left: 42px;

    height: 40px;
  }
  .icon-input {
    position: absolute;
    bottom: 11px;
    left: 12px;

    fill:  #212121;
    transition: fill 250ms cubic-bezier(0.4, 0, 0.2, 1);
  }
  .form-field:hover .icon-input,
  .form-field:focus .icon-input {
    fill: #2196f3;
  }
  .form-field input:hover,
  .form-field > textarea:hover,
  .form-field input:focus,
  .form-field > textarea:focus {
    border-color: #2196f3;
    cursor: pointer;
  }
  .form-field > textarea {
    width: 448px;
    height: 120px;
    resize: none;
    padding: 12px 16px 12px 16px;
    margin-bottom: 20px;

    border: 1px solid rgba(33, 33, 33, 0.2);
    border-radius: 4px;
    transition: border-color 250ms cubic-bezier(0.4, 0, 0.2, 1);
  }
  .form-field > textarea::placeholder {
    font-size: 12px;
    line-height: 1.17;
    letter-spacing: 0.01em;

    color: rgba(117, 117, 117, 0.5);
  }
