}

.eventBtnBox button {
	padding-bottom: 5px;
	border: none;
	background-color: white;
	color: black;
	font-size: 23px;
	width: 160px;
	transition: all 0.5s;
	cursor: pointer;
	outline: none;
	/* box-shadow: 1px 1px 3px #b3b3b3; */
}

.eventBtnBox button span {
	cursor: pointer;
	display: inline-block;
	position: relative;
	transition: 0.5s;
}

.eventBtnBox button span:after {
	font-family: "Glyphicons Halflings";
	font-size: 14px;
	content: "\e258";
	position: absolute;
	opacity: 0;
	top: 8px;
	right: -20px;
	transition: 0.5s;
}

.eventBtnBox button:hover span {
	padding-right: 22px;
}

.eventBtnBox button:hover span:after {
	opacity: 1;
	right: 0;
}

.eventsSpace {
	height: 5px;
}

