import "../../../Utils/expect.dart";
import "dart:async";
import "dart:convert";
import "dart:io";

int called = 0;

String str = "Testme";
List encodings = [utf8, ascii, latin1, systemEncoding];
List expected = [84, 101, 115, 116, 109, 101];

class MyStreamConsumer extends StreamConsumer<List<int>> {

  Future addStream(Stream<List<int>> stream) {
    stream.toList().then((x) {
      Expect.listEquals(expected, x[0]);
      called++;
    });
    return new Future(() {});
  }

  Future close() { return new Future(() {}); }
}

test() async {
  encodings.forEach((enc) async {
    called = 0;
    StreamConsumer<List<int>> consumer = new MyStreamConsumer();
    IOSink sink = new IOSink(consumer, encoding: enc);
    sink.write(str);
    await sink.close();
    Expect.equals(1, called);
  });
  asyncEnd();
}

main() {
  asyncStart();
  test();
}

