import 'package:flutter/material.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:registration_desk/widgets/form_stepper/form_stepper_preview.dart';
import 'package:registration_desk/widgets/test_bench.dart';

void main() {
  testWidgets('Should allow to enter text for the first step', (tester) async {
    var exampleStepper = ExampleStepper();
    await tester.open(exampleStepper);

    await tester.enterText(
      find.byKey(const ValueKey('firstStepInput')),
      'John Doe',
    );
    await tester.pump();

    expect(exampleStepper.firstStepInputController.text, equals('John Doe'));
  });

  testWidgets('Should go to next step', (tester) async {
    await tester.open(ExampleStepper());
    await tester.enterText(
      find.byKey(const ValueKey('firstStepInput')),
      'John Doe',
    );

    await goToNextStep(tester);

    expectOnSecondPage(tester);
  });

  testWidgets('Should go to previous step', (tester) async {
    await tester.open(ExampleStepper());
    await tester.enterText(
      find.byKey(const ValueKey('firstStepInput')),
      'John Doe',
    );
    await goToNextStep(tester);
    expectOnSecondPage(tester);

    await goToPreviousStep(tester);

    expectOnFirstPage(tester);
  });

  testWidgets('Should cancel stepper', (tester) async {
    var canceledHasBeenCalled = false;
    await tester.open(ExampleStepper(
      onCancel: () => canceledHasBeenCalled = true,
    ));

    var button = find.byKey(const ValueKey('cancelButton'));
    await tester.tap(button);

    expect(canceledHasBeenCalled, isTrue);
  });

  testWidgets('Should validate form before going to the next step',
      (tester) async {
    await tester.open(ExampleStepper());
    await tester.enterText(
      find.byKey(const ValueKey('firstStepInput')),
      '',
    );

    await goToNextStep(tester);

    expect(find.text('The input for the first step is mandatory.'),
        findsOneWidget);
  });

  testWidgets('Should not show back button on first wizard page',
      (tester) async {
    await tester.open(ExampleStepper());

    expect(find.byKey(const ValueKey('backButton')), findsNothing);
  });
}

Future goToNextStep(WidgetTester tester) async {
  var continueButton = find.byKey(const ValueKey('continueButton'));
  expect(continueButton, findsOneWidget);

  await tester.tap(continueButton);
  await tester.pump();
}

Future goToPreviousStep(WidgetTester tester) async {
  var button = find.byKey(const ValueKey('backButton'));
  expect(button, findsOneWidget);

  await tester.tap(button);
  await tester.pump();
}

void expectOnFirstPage(WidgetTester tester) {
  var inputField = find.byKey(const ValueKey('firstStepInput'));
  expect(inputField, findsOneWidget);

  var secondStepInputField = find.byKey(const ValueKey('secondStepInput'));
  expect(secondStepInputField, findsNothing);
}

void expectOnSecondPage(WidgetTester tester) {
  var inputField = find.byKey(const ValueKey('secondStepInput'));
  tester.verify(inputField, findsOneWidget);

  var firstStepInputField = find.byKey(const ValueKey('firstStepInput'));
  tester.verify(firstStepInputField, findsNothing);
}

extension WidgetTesterExtensions on WidgetTester {
  Future open(Widget widgetUnderTest) async {
    // Workaround to avoid pixel overflow errors
    binding.window.textScaleFactorTestValue = 0.2;
    return pumpWidget(TestBench(
      child: widgetUnderTest,
    ));
  }

  void printStringValueKeys() {
    print(
        '══╡ CURRENT STRING VALUE KEYS ╞═══════════════════════════════════════'
        '══════════════════════════════');
    allWidgets
        .map((widget) => widget.key)
        .whereType<ValueKey>()
        .map((key) => key.value)
        .whereType<String>()
        .toList()
        .forEach(print);
  }

  void verify(
    dynamic actual,
    dynamic matcher, {
    String? reason,
    dynamic skip, // true or a String
  }) {
    try {
      expect(actual, matcher, reason: reason, skip: skip);
    } on TestFailure catch (_) {
      printStringValueKeys();
      rethrow;
    }
  }
}

import 'baseValidator.dart';

final String usPhoneMatcher =
    r'^(?:(?:\+?1\s*(?:[.-]\s*)?)?(?:\(\s*([2-9]1[02-9]|[2-9][02-8]1|[2-9][02-8][02-9])\s*\)|([2-9]1[02-9]|[2-9][02-8]1|[2-9][02-8][02-9]))\s*(?:[.-]\s*)?)?([2-9]1[02-9]|[2-9][02-9]1|[2-9][02-9]{2})\s*(?:[.-]\s*)?([0-9]{4})(?:\s*(?:#|x\.?|ext\.?|extension)\s*(\d+))?$';
final String emailMatcher =
    r"^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$";

///A validator used to validate using regular expressions.  Out of the box we have various
///expressions ready for use - such as phone #s and email addresses.  But you may always
///add your own.
class RegExpValidator extends BaseValidator {
  late RegExp _regex;

  RegExpValidator(String key, String expression)
      : super(key, "$key is not valid.") {
    _regex = new RegExp(expression);
  }

  @override
  bool isValid(dynamic value) {
    return value == null || _regex.hasMatch(value);
  }

  static bool isValidUSPhoneNumber(String? value) {
    if (value == null) {
      return true;
    }
    RegExp r = new RegExp(usPhoneMatcher);
    return r.hasMatch(value);
  }

  static bool isValidEmailAddress(String? value) {
    if (value == null) {
      return true;
    }
    RegExp r = new RegExp(emailMatcher);
    return r.hasMatch(value);
  }
}

import 'package:mgramseva/utils/Constants/I18KeyConstants.dart';
import 'package:mgramseva/utils/Locilization/application_localizations.dart';
import 'package:mgramseva/utils/global_variables.dart';

class Validators {
  static validate(value, type) {
    if (type == 'Email') {
      String pattern =
          r'^(([^<>()[\]\\.,;:\s@\"]+(\.[^<>()[\]\\.,;:\s@\"]+)*)|(\".+\"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$';
      RegExp regex = new RegExp(pattern);
      return (regex.hasMatch(value)) ? null : 'Enter a valid Email';
    } else if (type == 'Mobile Number') {
      String pattern = r'^([0|\+[0-9]{1,5})?([7-9][0-9]{9})$';
      RegExp regex = new RegExp(pattern);
      return (regex.hasMatch(value)) ? null : 'Enter a valid mobile Number';
    } else if (type == 'OTP') {
      String pattern = r'^[0-9]+$';
      RegExp regex = new RegExp(pattern);
      return (regex.hasMatch(value))
          ? (value.length < 4)
              ? 'Enter a valid OTP'
              : null
          : 'Enter a valid OTP';
    } else if (type == 'Flat Id') {
      return (value.length < 3) ? 'Enter a valid Flat Id' : null;
    } else if (type == 'CORE_LOGIN_USERNAMEs') {
      String pattern = r'^[A-Za-z ]+$';
      RegExp regex = new RegExp(pattern);
      return (regex.hasMatch(value))
          ? (value.length < 3)
              ? 'Enter a valid Name'
              : null
          : 'Enter a valid Name';
    } else if (type == 'Password') {
      return (value.length < 8) ? 'Please provide  8 characters' : null;
    } else if (type == 'Old Password' ||
        type == 'New Password' ||
        type == 'Confirm Password')
      return (value.length < 8) ? 'Please provide  8 characters' : null;
  }

  static String? mobileNumberValidator(String? v) {
    if (v!.trim().isEmpty) {
      return '${ApplicationLocalizations.of(navigatorKey.currentContext!).translate(i18.validators.ENTER_MOBILE_NUMBER)}';
    } else if (!RegExp(r'^[0-9]+$').hasMatch(v)) {
      return '${ApplicationLocalizations.of(navigatorKey.currentContext!).translate(i18.validators.ENTER_NUMBERS_ONLY)}';
    } else if (v.trim().length != 10) {
      return '${ApplicationLocalizations.of(navigatorKey.currentContext!).translate(i18.validators.MOBILE_NUMBER_SHOULD_BE_10_DIGIT)}';
    }
    return null;
  }

  static String? passwordComparision(String? val, String label,
      [String? val1]) {
    if (val!.trim().isEmpty) {
      return '$label';
    } else if (!(RegExp(
            r'^(?=.*?[A-Za-z])(?=.*?[0-9])(?=.*?[#?!@$%^&*-]).{6,}$')
        .hasMatch(val))) {
      return '${ApplicationLocalizations.of(navigatorKey.currentContext!).translate(i18.validators.INVALID_FORMAT)}';
    } else if (val1 != null && val.trim() != val1.trim()) {
      return '${ApplicationLocalizations.of(navigatorKey.currentContext!).translate(i18.validators.CONFIRM_RECONFIRM_SHOULD_SAME)}';
    }
    return null;
  }

  static String? meterNumberValidator(String? v) {
    if (v!.trim().isEmpty) {
      return '${ApplicationLocalizations.of(navigatorKey.currentContext!).translate(i18.validators.ENTER_METER_NUMBER)}';
    } else if (!RegExp(r'^[a-zA-Z0-9]+$').hasMatch(v)) {
      return '${ApplicationLocalizations.of(navigatorKey.currentContext!).translate(i18.validators.ENTER_ALPHA_NUMERIC_ONLY)}';
    }
    return null;
  }

  static String? amountValidator(String? v) {
    if (v!.trim().isEmpty) {
      return '${ApplicationLocalizations.of(navigatorKey.currentContext!).translate(i18.expense.AMOUNT_MENTIONED_IN_THE_BILL)}';
    } else if (double.parse(v) <= 0) {
      return '${ApplicationLocalizations.of(navigatorKey.currentContext!).translate(i18.expense.ENTER_VALID_AMOUNT)}';
    }
    return null;
  }

  static String? rangeValidatior(String? v, double? inputnum) {
    if (v!.trim().isEmpty) {
      return '${ApplicationLocalizations.of(navigatorKey.currentContext!).translate(i18.validators.ENTER_METER_NUMBER)}';
    } else if (!RegExp(r'^[a-zA-Z0-9]+$').hasMatch(v)) {
      return '${ApplicationLocalizations.of(navigatorKey.currentContext!).translate(i18.validators.ENTER_ALPHA_NUMERIC_ONLY)}';
    } else if (double.parse(v) > (inputnum!)) {
      return '${ApplicationLocalizations.of(navigatorKey.currentContext!).translate(i18.validators.PARTIAL_AMT_OUT_OF_RANGE)}';
    }
    return null;
  }

  static String? partialAmountValidatior(String? v, double? inputnum) {
    if (v!.trim().isEmpty) {
      return '${ApplicationLocalizations.of(navigatorKey.currentContext!).translate(i18.validators.CANNOT_BE_EMPTY)}';
    } else if (!RegExp(r'^[0-9]+$').hasMatch(v)) {
      return '${ApplicationLocalizations.of(navigatorKey.currentContext!).translate(i18.validators.ENTER_NUMBERS_ONLY)}';
    } else if (double.parse(v) > (inputnum!)) {
      return '${ApplicationLocalizations.of(navigatorKey.currentContext!).translate(i18.validators.AMOUNT_EXCEEDS)}';
    }
    return null;
  }
}

