  final String? tag;
  final String text;
  final String? tooltip;

  final int? maxLines;
  final TextStyle? style;
  final TextAlign textAlign;

  final bool softWrap;

  const TooltipText({
    Key? key,
    this.tag,
    required this.text,
    this.tooltip,
    this.maxLines = 1,
    this.style,
    this.textAlign = TextAlign.start,
    this.softWrap = false,
  }) : super(key: key);

  @override
  Widget build(BuildContext context) {
    final child = Tooltip(
      message: tooltip ?? text,
      child: Text(
        text,
        textAlign: textAlign,
        overflow: TextOverflow.fade,
        maxLines: maxLines,
        softWrap: softWrap,
