package com.fundito.fundito.common.widget

import android.graphics.Paint
import android.graphics.Typeface

import android.text.TextPaint

import android.text.style.TypefaceSpan




/**
 * Created by mj on 31, December, 2019
 */
class CustomTypefaceSpan(family: String?, type: Typeface) : TypefaceSpan(family) {
    private val newType: Typeface = type
    override fun updateDrawState(ds: TextPaint) {
        applyCustomTypeFace(ds, newType)
    }

    override fun updateMeasureState(paint: TextPaint) {
        applyCustomTypeFace(paint, newType)
    }

    companion object {
        private fun applyCustomTypeFace(paint: Paint, tf: Typeface) {
            val oldStyle: Int
            val old: Typeface = paint.typeface
            oldStyle = old.style
            val fake = oldStyle and tf.style.inv()
            if (fake and Typeface.BOLD != 0) {
                paint.isFakeBoldText = true
            }
            if (fake and Typeface.ITALIC != 0) {
                paint.textSkewX = -0.25f
            }
            paint.typeface = tf
        }
    }

}

