    assertProblems("(a: A, b: B)", "(a = A, a = null, b = B, b = null)") {
      case ParameterSpecifiedMultipleTimes(Assignment("a = A")) ::
              ParameterSpecifiedMultipleTimes(Assignment("a = null")) ::
