 *
 * @author Chris de Vreeze
 */
class LewisStructureTest extends AnyFunSuite {

  import AufbauPrinciple._
  import ElementSymbol._
  import SimpleQueryApi._
  import LewisStructure._

  test("testElementN") {
    val lewisForN: LewisStructure = LewisStructure.builder.plusAtom(N.at(1), 5).build

    assertResult(true) {
      lewisForN.underlyingGraphIsTree
    }

    assertResult(getValenceElectronCount(N)) {
      lewisForN.getAtom(N.at(1)).loneElectronCount
    }
  }

  test("testUnconnectedStructure") {
    val wrongLewis: LewisStructure = LewisStructure.builder.plusAtom(C.at(1), 4).plusAtom(H.at(1), 1).build

    assertResult(false) {
      wrongLewis.underlyingGraphIsConnected
    }
  }

  test("testCyclicStructure") {
    val wrongLewis: LewisStructure = LewisStructure.builder.plusAtom(C.at(1), 4).plusAtom(O.at(1), 6).plusAtom(N.at(1), 5).build
      .makeBond(C.at(1), O.at(1)).makeBond(N.at(1), O.at(1)).makeBond(C.at(1), N.at(1))

    assertResult(true) {
      wrongLewis.underlyingGraphIsConnected
    }
    assertResult(false) {
      wrongLewis.getUnderlyingUndirectedGraph.hasNoCycles(C.at(1))
    }
    assertResult(false) {
      wrongLewis.underlyingGraphIsTree
    }

    // Let's change the "order" of an edge.
    val wrongLewis2: LewisStructure = LewisStructure.builder.plusAtom(C.at(1), 4).plusAtom(O.at(1), 6).plusAtom(N.at(1), 5).build
      .makeBond(C.at(1), O.at(1)).makeBond(N.at(1), O.at(1)).makeBond(N.at(1), C.at(1))

    assertResult(true) {
      wrongLewis2.underlyingGraphIsConnected
    }
    assertResult(false) {
      wrongLewis2.getUnderlyingUndirectedGraph.hasNoCycles(C.at(1))
    }
    assertResult(false) {
      wrongLewis2.underlyingGraphIsTree
    }

    // Let's add an unconnected vertex.
    val wrongLewis3: LewisStructure =
      LewisStructure.builder.plusAtom(C.at(1), 4).plusAtom(O.at(1), 6).plusAtom(N.at(1), 5).plusAtom(C.at(2), 4).build
        .makeBond(C.at(1), O.at(1)).makeBond(N.at(1), O.at(1)).makeBond(N.at(1), C.at(1)) // C.at(2) is unconnected

    assertResult(false) {
      wrongLewis3.underlyingGraphIsConnected
    }
    assertResult(false) {
      wrongLewis3.getUnderlyingUndirectedGraph.hasNoCycles(C.at(1))
    }
    assertResult(false) {
      wrongLewis3.underlyingGraphIsTree
    }
  }

  test("testElementCa") {
    val lewisForCa: LewisStructure = LewisStructure.builder.plusAtom(Ca.at(1), 2).build

    assertResult(true) {
      lewisForCa.underlyingGraphIsTree
    }

    assertResult(getValenceElectronCount(Ca)) {
      lewisForCa.getAtom(Ca.at(1)).loneElectronCount
    }
  }

  test("testElementC") {
    val lewisForC: LewisStructure = LewisStructure.builder.plusAtom(C.at(1), 4).build

    assertResult(true) {
      lewisForC.underlyingGraphIsTree
    }

    assertResult(getValenceElectronCount(C)) {
      lewisForC.getAtom(C.at(1)).loneElectronCount
    }
  }

  test("testWrongElementO") {
    intercept[RuntimeException] {
      LewisStructure.builder.plusAtom(O.at(1), 5).build
    }
  }

  test("testElementH") {
    val lewisForH: LewisStructure = LewisStructure.builder.plusAtom(H.at(1), 1).build

    assertResult(true) {
      lewisForH.underlyingGraphIsTree
    }

    assertResult(getValenceElectronCount(H)) {
      lewisForH.getAtom(H.at(1)).loneElectronCount
    }
  }

  test("testElementNe") {
    val lewisForNe: LewisStructure = LewisStructure.builder.plusAtom(Ne.at(1), 8).build

    assertResult(true) {
      lewisForNe.underlyingGraphIsTree
    }

    assertResult(getValenceElectronCount(Ne)) {
      lewisForNe.getAtom(Ne.at(1)).loneElectronCount
    }
  }

  test("testCO2") {
